-- {name}: usage & governance gold layer (refreshed hourly by job "{app}-usage"). Generated by install/install.py.
-- 1. Staging copy of the app history (Lakebase, registered in UC as {lb})
CREATE OR REPLACE TABLE {fq}.stg_turns AS
SELECT t.id, t.conversation_id, t.user_text, t.status, t.created_at, CAST(t.events AS STRING) AS events_json,
       -- events parsed once (robust to how the JSONB is serialised: spacing, key order)
       from_json(CAST(t.events AS STRING), 'array<struct<type:string,tool:string,kind:string,text:string,label:string>>') AS ev,
       c.user_email, c.department, c.title
FROM {lb}.assistant.turns t
JOIN {lb}.assistant.conversations c ON c.id = t.conversation_id;

CREATE OR REPLACE TABLE {fq}.stg_files AS
SELECT name, title, kind, path, created_at, conversation_id, user_email FROM {lb}.assistant.files;

-- 2. Requests classified with ai_classify (type of use + inferred business domain)
CREATE OR REPLACE TABLE {fq}.gold_assistant_requests
COMMENT 'Requêtes {name_sql} : une ligne par demande utilisateur, classée par ai_classify (type d\'usage, métier inféré).'
AS
SELECT id AS turn_id, conversation_id, user_email, COALESCE(department, 'Non renseigné') AS service_declare,
       created_at, DATE(created_at) AS jour, user_text,
       exists(ev, e -> e.type = 'blocked') AS bloque,
       NULLIF(regexp_extract(get(filter(ev, e -> e.type = 'blocked'), 0).text, 'Bloqué par la politique « ([^»]+) »', 1), '') AS politique_bloquante,
       size(filter(ev, e -> e.type = 'tool' AND e.tool = 'genie')) AS appels_genie_one,
       CASE WHEN exists(ev, e -> e.type = 'file' AND e.kind = 'pptx') THEN 'PowerPoint'
            WHEN exists(ev, e -> e.type = 'file' AND e.kind = 'docx') THEN 'Word'
            WHEN exists(ev, e -> e.type = 'file' AND e.kind = 'html') THEN 'Page web'
            WHEN exists(ev, e -> e.type = 'blocked') THEN 'Bloqué'
            ELSE 'Réponse dans le chat' END AS livrable,
       -- requests blocked by a policy are never sent to a model again (ai_classify runs on the Databricks-hosted AI Functions model,
       -- inside the workspace but outside the model-service policies): they are labelled directly
       CASE WHEN exists(ev, e -> e.type = 'blocked') THEN 'Tentative contraire à la politique'
            ELSE ai_classify(user_text, ARRAY('Rapport 8D / résolution de problème', 'Présentation PowerPoint',
                                              'Compte rendu, note ou mail', 'Question sur les données de l’usine',
                                              'Synthèse ou lecture de document')) END AS type_usage,
       CASE WHEN exists(ev, e -> e.type = 'blocked') THEN 'Non classé (bloqué)'
            ELSE ai_classify(user_text, ARRAY('Qualité', 'Maintenance', 'Production', 'R&D / Ingénierie', 'Direction')) END AS metier_infere
FROM {fq}.stg_turns
WHERE status = 'done';

-- 3. Unity AI Gateway traffic for the assistant services.
--    Genie One usage is account-wide: only calls made during one of this app's requests (same user, within 15 min) are kept. (model services + Genie One MCP)
CREATE OR REPLACE VIEW {fq}.gold_gateway_usage
COMMENT 'Trafic Unity AI Gateway des services {company_sql} (bureautique, développeur, Genie One). Coût estimé au prix catalogue configuré ; Genie One gratuit pour les utilisateurs jusqu\'au 31/01/2027.'
AS
SELECT event_time, DATE(event_time) AS jour, HOUR(event_time) AS heure, service_name, service_type,
       CASE WHEN service_name = '{assistant_fq}' THEN 'Bureautique'
            WHEN service_name = '{developer_fq}' THEN 'Développeur'
            WHEN service_name = 'system.ai.genie_one_mcp' THEN 'Genie One (données & documents)' END AS pilier,
       CASE WHEN requester = '{sp}' THEN '{name_sql} (app)' ELSE requester END AS utilisateur,
       requester_type, auth_mode,
       COALESCE(request_tags['department'], CASE WHEN service_name = '{developer_fq}' THEN 'Développement' END, 'Non renseigné') AS service_metier,
       COALESCE(session_metadata.coding_agent, CASE WHEN service_name = '{developer_fq}' THEN 'agent de code' END) AS agent_code,
       mcp_metadata.tool_name AS outil_mcp, mcp_metadata.json_rpc_method AS methode_mcp, api_type, destination_model AS modele,
       CASE WHEN service_type = 'MODEL_SERVICE' AND destination_model IS NULL THEN true ELSE false END AS bloque_par_politique,
       input_tokens, output_tokens, total_tokens, token_details.cache_read_input_tokens AS tokens_cache, token_details.output_reasoning_tokens AS tokens_raisonnement,
       latency_ms, time_to_first_byte_ms AS ttfb_ms, status_code, size(routing_information.attempts) AS tentatives_routage,
       CASE {price_cases}
            WHEN service_name = 'system.ai.genie_one_mcp' THEN 0.0 END AS cout_estime_usd,
       model_metadata.gateway_feature_results.service_policies AS politiques
FROM system.ai_gateway.usage
WHERE workspace_id = '{workspace_id}'
  AND (service_name IN ('{assistant_fq}', '{developer_fq}')
       OR (service_name = 'system.ai.genie_one_mcp' AND (requester = '{sp}' OR EXISTS (SELECT 1 FROM {fq}.stg_turns t
            WHERE t.user_email = requester AND event_time BETWEEN t.created_at AND t.created_at + INTERVAL 15 MINUTES))));

-- 4. Guardrail decisions. The gateway does not expose per-policy decisions in system tables or inference tables today,
--    so DENY decisions come from the app, which receives databricks_service_policy (name + reason) on every block.
CREATE OR REPLACE VIEW {fq}.gold_policy_decisions
COMMENT 'Blocages par les politiques AI Gateway (anti-fuite PI, jailbreak…) observés par {name_sql} : politique, raison, utilisateur.'
AS
SELECT r.created_at AS event_time, r.jour, 'Bureautique' AS pilier, r.user_email AS utilisateur, r.service_declare AS service_metier,
       COALESCE(r.politique_bloquante, 'politique') AS politique, 'pre_call' AS phase, 'DENY' AS decision,
       regexp_extract(get(filter(t.ev, e -> e.type = 'blocked'), 0).text, 'Bloqué par la politique « [^»]+ » : (.*)$', 1) AS raison, r.user_text AS demande
FROM {fq}.gold_assistant_requests r
JOIN {fq}.stg_turns t ON t.id = r.turn_id
WHERE r.bloque;

-- 5. Agent tool calls inside the assistant (Genie One, PowerPoint, Word) from the app history
CREATE OR REPLACE TABLE {fq}.gold_agent_tools
COMMENT 'Appels d\'outils de l\'agent {name_sql} (Genie One, génération PowerPoint, génération Word), une ligne par appel.'
AS
SELECT t.id AS turn_id, t.user_email, COALESCE(t.department, 'Non renseigné') AS service_declare, t.created_at, DATE(t.created_at) AS jour,
       CASE WHEN e.tool IN ('genie', 'Genie One') THEN 'Genie One (MCP)' WHEN e.tool IN ('pptx', 'PowerPoint') THEN 'Génération PowerPoint'
            WHEN e.tool IN ('docx', 'Word') THEN 'Génération Word' ELSE e.tool END AS outil,
       COALESCE(regexp_replace(e.label, '^Lecture de [0-9]+ documents?$', 'Lecture de documents'),
                CASE WHEN e.tool = 'Genie One' THEN 'Analyse des données de l\'usine' WHEN e.tool = 'PowerPoint' THEN 'Création de la présentation'
                     WHEN e.tool = 'Word' THEN 'Rédaction du document Word' END) AS action
FROM {fq}.stg_turns t
LATERAL VIEW explode(t.ev) x AS e
WHERE e.type = 'tool'
